referenceSolutions.javascript:
export function solve(value) {
  function walk(v) {
    if (Array.isArray(v)) return v.map(walk);
    if (v !== null && typeof v === "object")
      return Object.fromEntries(
        Object.entries(v).map(([k, x]) => [
          k.replace(/_([a-z])/g, (_, c) => c.toUpperCase()),
          walk(x),
        ]),
      );
    return v;
  }
  return walk(value);
}

referenceSolutions.typescript:
type Value = any;
export function solve(value: Value): Value {
  function walk(v: Value): Value {
    if (Array.isArray(v)) return v.map(walk);
    if (v !== null && typeof v === "object")
      return Object.fromEntries(
        Object.entries(v).map(([k, x]: Value) => [
          k.replace(/_([a-z])/g, (_: Value, c: Value) => c.toUpperCase()),
          walk(x),
        ]),
      );
    return v;
  }
  return walk(value);
}
